class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def swapKthNodes(nums, k):
    head = build(nums)
    first = head
    for _ in range(k - 1):
        first = first.next
    second = head
    walker = first
    while walker.next:
        walker = walker.next
        second = second.next
    first.val, second.val = second.val, first.val
    return dump(head)
